using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(storageRootPath: "eval-reports");
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static IEnumerable<IEvaluator> GetEvaluators(IChatClient chatClient) =>
    [
        new CoherenceEvaluator(chatClient),
        new RelevanceEvaluator(chatClient),
        new FluencyEvaluator(chatClient),
    ];

    [TestMethod]
    public async Task ChatRespondsCoherently()
    {
        await using var appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluators = GetEvaluators(chatClient);
        var evaluationResult = await evaluators.EvaluateAsync(messages, response, s_reportingConfiguration!.CreateScenarioRun(nameof(ChatRespondsCoherently)));

        foreach (var metric in evaluationResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue { Value: >= 3 },
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }

    [TestMethod]
    public async Task ChatHandlesFollowUpQuestions()
    {
        await using var appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about renewable energy."),
            new(ChatRole.Assistant, "Renewable energy comes from sources that are naturally replenished, such as solar, wind, hydro, and geothermal power."),
            new(ChatRole.User, "Which one is most widely used globally?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluators = GetEvaluators(chatClient);
        var evaluationResult = await evaluators.EvaluateAsync(messages, response, s_reportingConfiguration!.CreateScenarioRun(nameof(ChatHandlesFollowUpQuestions)));

        foreach (var metric in evaluationResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue { Value: >= 3 },
                $"Metric '{metric.Key}' scored below threshold.");
        }
    }
}

